PARAM_SPECS = {
    "pressure_distance_m": (1.0, 8.0, 4.5),
    "safe_approach_angle_deg": (60.0, 150.0, 90.0),
    "space_after_beat_m": (2.0, 10.0, 4.5),
    "support_min_count": (0.0, 3.0, 1.0),
    "sideline_risk_distance_m": (1.0, 8.0, 3.0),
    "congestion_max_count": (1.0, 6.0, 4.0),
    "goal_line_opportunity_m": (10.0, 40.0, 25.0),
}

def predict_take_on(f: dict, p: dict) -> int:
    is_under_pressure = f["distance_m"] < p["pressure_distance_m"]

    is_defender_head_on = f["approach_angle_deg"] < p["safe_approach_angle_deg"]

    has_space_beyond = f["second_nearest_dist_m"] > p["space_after_beat_m"]

    has_enough_support = f["n_supporting_teammates"] >= p["support_min_count"]

    is_pinned_to_sideline = f["dist_to_sideline_m"] < p["sideline_risk_distance_m"]

    is_congested = f["n_opponents_nearby_10m"] > p["congestion_max_count"]

    is_attacking_zone = f["dist_to_goal_line_m"] < p["goal_line_opportunity_m"]

    was_previous_pass = bool(f["prev_event_was_pass"])

    positive_score = 0
    negative_score = 0

    if has_space_beyond:
        positive_score += 1
    if has_enough_support:
        positive_score += 1
    if is_attacking_zone:
        positive_score += 1
    if not is_defender_head_on:
        positive_score += 1
    if was_previous_pass:
        positive_score += 1

    if is_congested:
        negative_score += 1
    if is_pinned_to_sideline and not has_space_beyond:
        negative_score += 1
    if is_under_pressure and is_defender_head_on and not has_space_beyond:
        negative_score += 1

    take_on = positive_score >= 2 and negative_score == 0

    if not is_under_pressure:
        take_on = has_space_beyond and not is_congested

    return 1 if take_on else 0
